export default {
	data() {
		return {
			isShowNavBar: false, // 是否需要导航栏

			username: '',
			userpwd: '',
			pwdType: 'password'
		};
	},

	onLoad() {
		var pages = getCurrentPages();
		this.isShowNavBar = pages.length > 1;

	},

	methods: {
		inputUsername(e) {
			this.username = e.target.value;
		},
		inputPwd(e) {
			this.userpwd = e.target.value;
		},
		delUser() {
			this.username = '';
		},
		switchPwd() {
			this.pwdType = this.pwdType === 'text' ? 'password' : 'text';
		},
		login() {
			const username = this.username,
				userpwd = this.userpwd;

			if (!username.trim()) {
				this.$common.toast('请输入账号');
				return;
			}
			if (!userpwd.trim()) {
				this.$common.toast('请输入密码');
				return;
			}
			const params = {
				userName: username,
				password: userpwd
			};
			this.$api({
				url: '/user/login',
				data: params,
				notToken: true
			})
				.then(async res => {
					if (res) {
						await this.$common.setStorage('token', res.token);
						await this.$common.setStorage('userInfo', res);
						this.$store.commit('SETTOKEN', res.token);
						this.$store.commit('SETUSERINFO', res);
						// 重定向到成员页面
						uni.switchTab({
							url: '/pages/index/index'
						});
					}

				})
				.catch(e => {
					this.$common.toast(e.msg);
				});
		},
		findPwd() {
			this.$common.showModal({
				content: '以家庭身份登录后，点击成员头像可修改成员密码',
				showCancel: true,
				success: () => {
					uni.navigateTo({
						url: '/pages/family/login'
					});
				}
			});
		},
		goReg() {
			this.$common.showModal({
				content: '请以家庭身份登录后添加成员',
				showCancel: true,
				success: () => {
					uni.navigateTo({
						url: '/pages/family/login'
					});
				}
			});
		}
	}
};
